from a12_r9_orig import *
server='saga-server@192.168.100.151'
sql=r"""BEGIN READ ONLY;SET LOCAL statement_timeout='7s';SET LOCAL search_path=adempiere,pg_catalog;
WITH names(t) AS(VALUES('EVA_DocPartener'),('EVA_ComandaPlatforma'),('EVA_DecontCurier'),('EVA_DecontCurierLinie'),('EVA_CorelareDecont'),('EVA_DiferentaDecont'),('EVA_ComandaSite'),('EVA_ComandaSiteLinie')) SELECT n.t,COALESCE(max(ad.tablename),'-'),count(DISTINCT ad.ad_table_id),count(DISTINCT ac.ad_column_id),(to_regclass('adempiere.'||lower(n.t))is not null) FROM names n LEFT JOIN ad_table ad ON lower(ad.tablename)=lower(n.t) AND ad.isactive='Y' LEFT JOIN ad_column ac ON ac.ad_table_id=ad.ad_table_id AND ac.isactive='Y' GROUP BY n.t ORDER BY n.t;
select c.columnname from ad_column c join ad_table a on a.ad_table_id=c.ad_table_id where lower(a.tablename)='eva_decontcurierlinie' and lower(c.columnname) in ('eva_decontcurier_id','eva_awb','c_invoice_id','c_order_id','eva_starelegare','eva_suma','eva_cauza','eva_coddiferenta') order by c.columnname;
ROLLBACK;"""
p=subprocess.run(['ssh','-o','BatchMode=yes',server,'docker exec -i eva-postgres-cesiro sh -c \'exec psql -XqAt -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d idempiere\''],input=sql.encode(),capture_output=True,timeout=15);assert p.returncode==0,p.stderr.decode();f=P9/'Dictionar_T04_CESIRO.json';strs=p.stdout.decode().splitlines();wr(f,{'utc':now(),'tenant_version':'CESIRO idempiere, schema adempiere; SQL metadata only','statement':sql,'output':strs,'oracle':'Comparație între numele planificate și tabelele instalate active și cheia nativă; nu între denumiri inventate și prezumția de lipsă a funcției.','no_business_records_read':True,'qualification':'Prezența tabelei, coloanelor și a legăturii de dicționar nu dovedește singură salvarea fișierelor sau reconcilierea integrală.'});print(sha(f),strs)

